<template><div class="app-container"><el-form :inline="true" :model="query"><el-form-item label="策略名称"><el-input v-model="query.strategyName" clearable @keyup.enter="load"/></el-form-item><el-button type="primary" @click="load">查询</el-button></el-form><el-button type="primary" icon="Plus" @click="openAdd" v-hasPermi="['research:strategy:add']">新增策略</el-button><el-table v-loading="loading" :data="rows" class="mt12"><el-table-column prop="strategyName" label="策略名称" width="220"/><el-table-column prop="combinationId" label="组合ID" width="100"/><el-table-column prop="description" label="策略说明" show-overflow-tooltip/><el-table-column prop="status" label="状态" width="100"/><el-table-column label="操作" width="90"><template #default="{row}"><el-button link type="danger" @click="remove(row)" v-hasPermi="['research:strategy:remove']">删除</el-button></template></el-table-column></el-table><pagination v-show="total" :total="total" v-model:page="query.pageNum" v-model:limit="query.pageSize" @pagination="load"/><el-dialog v-model="dialog" title="新增交易策略" width="500px"><el-form ref="formRef" :model="form" :rules="rules" label-width="90px"><el-form-item label="策略名称" prop="strategyName"><el-input v-model="form.strategyName"/></el-form-item><el-form-item label="组合ID" prop="combinationId"><el-input-number v-model="form.combinationId" :min="1"/></el-form-item><el-form-item label="策略说明"><el-input v-model="form.description" type="textarea"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
<script setup name="ResearchStrategy">import { addStrategy, delStrategy, listStrategy } from '@/api/project-research/research'
const { proxy }=getCurrentInstance();const loading=ref(false),dialog=ref(false),total=ref(0),rows=ref([]),formRef=ref();const query=reactive({pageNum:1,pageSize:10,strategyName:undefined});const form=reactive({});const rules={strategyName:[{required:true,message:'策略名称不能为空'}],combinationId:[{required:true,message:'请输入组合ID'}]};function load(){loading.value=true;listStrategy(query).then(r=>{rows.value=r.rows;total.value=r.total}).finally(()=>loading.value=false)}function openAdd(){Object.assign(form,{strategyName:'',combinationId:undefined,description:'',status:'enabled'});dialog.value=true}function save(){formRef.value.validate(v=>{if(v)addStrategy(form).then(()=>{proxy.$modal.msgSuccess('创建成功');dialog.value=false;load()})})}function remove(r){proxy.$modal.confirm('确认删除该交易策略吗？').then(()=>delStrategy(r.id)).then(load)}load()</script><style scoped>.mt12{margin-top:12px}</style>
